var text = $('Daily Quote Engine').first().json.imageText;
var fName = $('Daily Quote Engine').first().json.fileName;
var capRaw = $('Daily Quote Engine').first().json.caption;
var dayNum = $('Daily Quote Engine').first().json.dayOfYear || 1;
var capText = capRaw.split('\n')[0].toUpperCase();

var W = 800, H = 800, stride = 1 + W;
var CT = new Int32Array(256);
for (var ci = 0; ci < 256; ci++) { var cv = ci; for (var ck = 0; ck < 8; ck++) cv = cv & 1 ? 0xEDB88320 ^ (cv >>> 1) : cv >>> 1; CT[ci] = cv; }
function u4(v) { return Buffer.from([(v>>>24)&0xFF,(v>>>16)&0xFF,(v>>>8)&0xFF,v&0xFF]); }
function mkC(t, d) {
  var tb = Buffer.from(t), db = Buffer.isBuffer(d) ? d : Buffer.from(d), c = -1;
  for (var i = 0; i < tb.length; i++) c = CT[(c ^ tb[i]) & 0xFF] ^ (c >>> 8);
  for (var i = 0; i < db.length; i++) c = CT[(c ^ db[i]) & 0xFF] ^ (c >>> 8);
  return Buffer.concat([u4(db.length), tb, db, u4((c ^ -1) >>> 0)]);
}
function zlibS(data) {
  var M = 65535, p = [Buffer.from([0x78, 0x01])], o = 0;
  while (o < data.length) {
    var sz = Math.min(data.length - o, M), last = o + sz >= data.length ? 1 : 0;
    var h = Buffer.alloc(5);
    h[0] = last; h[1] = sz & 0xFF; h[2] = (sz >> 8) & 0xFF; h[3] = (~sz) & 0xFF; h[4] = (~sz >> 8) & 0xFF;
    p.push(h, data.slice(o, o + sz)); o += sz;
  }
  var sa = 1, sb = 0;
  for (var i = 0; i < data.length;) { var end = Math.min(i + 3000, data.length); for (var j = i; j < end; j++) { sa += data[j]; sb += sa; } sa %= 65521; sb %= 65521; i = end; }
  p.push(u4((sb << 16) | sa)); return Buffer.concat(p);
}

var FN = {};
FN.A=[14,17,17,31,17,17,17]; FN.B=[30,17,17,30,17,17,30]; FN.C=[14,17,16,16,16,17,14];
FN.D=[30,17,17,17,17,17,30]; FN.E=[31,16,16,30,16,16,31]; FN.F=[31,16,16,30,16,16,16];
FN.G=[14,17,16,23,17,17,14]; FN.H=[17,17,17,31,17,17,17]; FN.I=[31,4,4,4,4,4,31];
FN.J=[7,1,1,1,17,17,14]; FN.K=[17,18,20,24,20,18,17]; FN.L=[16,16,16,16,16,16,31];
FN.M=[17,27,21,21,17,17,17]; FN.N=[17,25,21,19,17,17,17]; FN.O=[14,17,17,17,17,17,14];
FN.P=[30,17,17,30,16,16,16]; FN.Q=[14,17,17,17,21,18,13]; FN.R=[30,17,17,30,20,18,17];
FN.S=[14,17,16,14,1,17,14]; FN.T=[31,4,4,4,4,4,4]; FN.U=[17,17,17,17,17,17,14];
FN.V=[17,17,17,17,10,10,4]; FN.W=[17,17,17,21,21,27,17]; FN.X=[17,17,10,4,10,17,17];
FN.Y=[17,17,10,4,4,4,4]; FN.Z=[31,1,2,4,8,16,31];
FN['0']=[14,17,19,21,25,17,14]; FN['1']=[4,12,4,4,4,4,31]; FN['2']=[14,17,1,6,8,16,31];
FN['3']=[14,17,1,6,1,17,14]; FN['4']=[2,6,10,18,31,2,2]; FN['5']=[31,16,30,1,1,17,14];
FN['6']=[14,16,16,30,17,17,14]; FN['7']=[31,1,2,4,8,8,8]; FN['8']=[14,17,17,14,17,17,14];
FN['9']=[14,17,17,15,1,1,14]; FN[' ']=[0,0,0,0,0,0,0];
FN['.']=[0,0,0,0,0,6,6]; FN[',']=[0,0,0,0,0,6,4]; FN['!']=[4,4,4,4,4,0,4];
FN['-']=[0,0,0,14,0,0,0]; FN[':']=[0,6,6,0,6,6,0]; FN['?']=[14,17,2,4,4,0,4];
FN['/']=[2,2,4,8,16,16,16];

var raw = Buffer.alloc(H * stride);
function dR(x0, y0, w, h, ci) {
  for (var dy = 0; dy < h; dy++) {
    var yy = y0 + dy; if (yy < 0 || yy >= H) continue;
    var base = yy * stride + 1;
    for (var dx = 0; dx < w; dx++) { var xx = x0 + dx; if (xx >= 0 && xx < W) raw[base + xx] = ci; }
  }
}
function dRR(x0, y0, w, h, r, ci, top, bot) {
  for (var dy = 0; dy < h; dy++) {
    var y = y0 + dy; if (y < 0 || y >= H) continue;
    var ins = 0;
    if (top && dy < r) { var dd = r - dy; ins = Math.ceil(r - Math.sqrt(r*r - dd*dd)); }
    else if (bot && dy >= h - r) { var dd = r - (h-1-dy); ins = Math.ceil(r - Math.sqrt(r*r - dd*dd)); }
    var base = y * stride + 1;
    for (var x = Math.max(0, x0+ins); x < Math.min(W, x0+w-ins); x++) raw[base + x] = ci;
  }
}
function dCirc(cx, cy, r, ci) {
  for (var dy = -r; dy <= r; dy++) {
    var yy = cy + dy; if (yy < 0 || yy >= H) continue;
    var dx = Math.floor(Math.sqrt(r*r - dy*dy));
    var base = yy * stride + 1;
    for (var x = Math.max(0, cx-dx); x <= Math.min(W-1, cx+dx); x++) raw[base + x] = ci;
  }
}
function dCh(ch, x0, y0, sc, ci) {
  var rows = FN[ch] || FN[' '];
  for (var row = 0; row < 7; row++) for (var col = 0; col < 5; col++)
    if (rows[row] & (1 << (4 - col))) dR(x0+col*sc, y0+row*sc, sc, sc, ci);
}
function dLn(txt, cy, sc, ci) {
  var tw = txt.length * 6 * sc - sc;
  var x = Math.round(W/2 - tw/2);
  for (var i = 0; i < txt.length; i++) { dCh(txt[i], x, cy, sc, ci); x += 6*sc; }
}
function wrap(txt, mw, sc) {
  var mc = Math.floor((mw + sc) / (6*sc)), ws = txt.split(' '), ls = [], ln = '';
  for (var i = 0; i < ws.length; i++) {
    var t = ln ? ln + ' ' + ws[i] : ws[i];
    if (t.length > mc && ln) { ls.push(ln); ln = ws[i]; } else { ln = t; }
  }
  if (ln) ls.push(ln); return ls;
}

dRR(55, 90, 690, 300, 18, 1, true, false);
dRR(55, 390, 690, 340, 18, 2, false, true);
dCirc(375, 50, 5, 3); dCirc(400, 50, 5, 3); dCirc(425, 50, 5, 3);

var words = text.toUpperCase().split(' ');
var sp = Math.max(1, Math.floor(words.length / 2));
var l1 = words.slice(0, sp).join(' '), l2 = words.slice(sp).join(' ');
var ml = Math.max(l1.length, l2.length);
var ts = Math.min(Math.floor(620 / (ml * 6)), 14);
var th = 2 * 7 * ts + ts * 2;
var ty = 90 + Math.round((300 - th) / 2);

dLn(l1, ty, ts, 4);
dLn(l2, ty + 7*ts + ts*2, ts, 3);

var cls = wrap(capText, 620, 3);
for (var i = 0; i < cls.length && i < 5; i++) dLn(cls[i], 420 + i * 30, 3, 5);

// DYNAMIC DAY BUTTON
var dayStr = dayNum.toString();
if (dayStr.length === 1) dayStr = '00' + dayStr;
if (dayStr.length === 2) dayStr = '0' + dayStr;
var bt = 'DAY ' + dayStr + ' / 365';
var btw = bt.length * 18 - 3;
var bw = btw + 40, bh = 35, bx = Math.round(W/2 - bw/2), by2 = 640;
dRR(bx, by2, bw, bh, 8, 3, true, true);
var btx = Math.round(W/2 - btw/2), bty = by2 + Math.round((bh - 21) / 2);
for (var i = 0; i < bt.length; i++) { dCh(bt[i], btx, bty, 3, 6); btx += 18; }

var wx = 680, wy = 700;
dCh('V', wx, wy, 2, 7); dCh('2', wx+12, wy, 2, 7); dCh('S', wx+24, wy, 2, 7);

var comp = zlibS(raw);
var sig = Buffer.from([137,80,78,71,13,10,26,10]);
var ihd = Buffer.concat([u4(W), u4(H), Buffer.from([8, 3, 0, 0, 0])]);

// DYNAMIC COLOR PALETTE
var acColors = [
  [46, 204, 113], // Green
  [52, 152, 219], // Blue
  [155, 89, 182], // Purple
  [231, 76, 60],  // Red
  [241, 196, 15], // Yellow
  [230, 126, 34], // Orange
  [0, 255, 255],  // Cyan
];
var ac = acColors[dayNum % acColors.length];

var pal = Buffer.from([
  18,18,24,     // 0: Background
  30,33,42,     // 1: Top Card
  22,25,32,     // 2: Bottom Card
  ac[0], ac[1], ac[2], // 3: Dynamic Accent
  255,255,255,  // 4: White
  150,155,170,  // 5: Grey text
  18,22,28,     // 6: Button Text (Dark)
  55,58,65      // 7: Watermark
]);
var png = Buffer.concat([sig, mkC('IHDR', ihd), mkC('PLTE', pal), mkC('IDAT', comp), mkC('IEND', Buffer.alloc(0))]);
var b64 = png.toString('base64');
return [{
  json: { imageText: text, caption: capRaw, fileName: fName },
  binary: { data: { data: b64, mimeType: 'image/png', fileType: 'image', fileName: fName, fileExtension: 'png' } }
}];

// Image is already validated and named by Generate Poster Image node
// Just pass through and confirm binary exists
const item = $input.first();

if (!item.binary || !item.binary.data) {
  throw new Error('NO BINARY DATA: Poster generation failed. Check the Generate Poster Image node logs.');
}

// Confirm metadata
item.binary.data.fileName = $('Daily Quote Engine').first().json.fileName;
item.binary.data.fileExtension = 'png';
item.binary.data.mimeType = 'image/png';

return [item];

